<template>
  <LabelingWrapper
    :enabled="hasLabeling"
    :wrapper-class="['space-y-1.5', attrs.class]"
    :wrapper-style="attrs.style as StyleValue"
  >
    <InputLabel
      v-if="props.label || $slots.label"
      :id="labelId"
      :for-id="inputId"
      :label="props.label"
      :required="props.required"
    >
      <template v-if="$slots.label" #default="slotProps">
        <slot name="label" v-bind="slotProps" />
      </template>
    </InputLabel>
    <textarea
      ref="textareaRef"
      :placeholder="placeholder"
      :class="[inputClasses, hasLabeling ? null : (attrs.class as any)]"
      :style="hasLabeling ? null : (attrs.style as any)"
      :disabled="disabled"
      :id="inputId"
      :value="modelValue"
      :rows="rows"
      :required="required"
      :aria-required="required || undefined"
      :aria-invalid="hasError || undefined"
      :aria-errormessage="hasError ? errorMessageId : undefined"
      :aria-describedby="describedBy"
      data-slot="control"
      v-bind="{ ...dataAttrs, ...attrsWithoutClassStyle }"
      @input="handleChange"
      @change="handleChange"
    />
    <InputDescription
      v-if="showDescription || $slots.description"
      :id="descriptionId"
      :description="props.description"
    >
      <slot v-if="$slots.description" name="description" />
    </InputDescription>
    <InputError v-if="hasError" :id="errorMessageId" :lines="errorLines" />
  </LabelingWrapper>
</template>

<script setup lang="ts">
import { computed, ref, useAttrs } from 'vue'
import type { StyleValue } from 'vue'
import debounce from '../../utils/debounce'
import { resolvePropValue } from '../../utils/resolvePropValue'
import { useInputLabeling } from '../../composables/useInputLabeling'
import { useReactiveSlots } from '../../composables/useReactiveSlots'
import InputLabel from '../InputLabeling/InputLabel.vue'
import InputDescription from '../InputLabeling/InputDescription.vue'
import InputError from '../InputLabeling/InputError.vue'
import LabelingWrapper from '../InputLabeling/LabelingWrapper.vue'
import type { InputSize } from '../../composables/inputTypes'
import type { TextareaEmits, TextareaProps } from './types'
import type { TextInputExposed } from '../TextInput/types'

defineOptions({
  inheritAttrs: false,
})

const props = withDefaults(defineProps<TextareaProps>(), {
  size: 'sm',
  variant: 'subtle',
  rows: 3,
})

const SIZE_FALLBACK = 'sm'
const SIZE_CONTEXT = { component: 'Textarea', prop: 'size' } as const

const sizeClassMap: Record<InputSize, string> = {
  xs: 'text-p-sm rounded-3 min-h-8',
  sm: 'text-p-sm rounded-4 min-h-9',
  md: 'text-p-sm rounded-4 min-h-10',
  lg: 'text-p-sm rounded-5 min-h-11',
}

const paddingClassMap: Record<InputSize, string[]> = {
  xs: ['py-1 px-1.5'],
  sm: ['py-1.5 px-2'],
  md: ['py-1.5 px-2.5'],
  lg: ['py-1.5 px-3'],
}

const emit = defineEmits<TextareaEmits>()
const attrs = useAttrs()
const slots = useReactiveSlots<typeof declaredSlots>()
const textareaRef = ref<HTMLTextAreaElement | null>(null)

const declaredSlots = defineSlots<{
  /** Overrides the rendered label content. Receives `{ required }`. */
  label?: (props: { required: boolean }) => any

  /** Overrides the rendered description content. */
  description?: () => any
}>()

const {
  inputId,
  labelId,
  descriptionId,
  errorMessageId,
  describedBy,
  hasError,
  errorLines,
  showDescription,
  rendersDescription,
  dataAttrs,
} = useInputLabeling(props, {
  size: () => props.size,
  variant: () => props.variant,
  disabled: () => props.disabled,
  hasLabelSlot: () => Boolean(slots.label),
  hasDescriptionSlot: () => Boolean(slots.description),
})

const hasLabeling = computed(() => {
  return Boolean(
    props.label || slots.label || rendersDescription.value || hasError.value,
  )
})

const attrsWithoutClassStyle = computed(() => {
  return Object.fromEntries(
    Object.entries(attrs).filter(([key]) => key !== 'class' && key !== 'style'),
  )
})

const inputClasses = computed(() => {
  // `size` moves spacing, radius and the minimum height — not the type. The
  // text is a flat 13px (`text-p-sm`) at every size, matching the label and
  // description; the single-line input heights do not prescribe a Textarea
  // height, so a `lg` Textarea is a roomier box of the same 13px prose.
  //
  // Every min-height still fits one full line: 13px x 1.5 line-height, plus
  // the size's vertical padding, plus 2px of border.
  let sizeClasses = resolvePropValue(
    sizeClassMap,
    props.size,
    SIZE_FALLBACK,
    SIZE_CONTEXT,
  )

  let paddingClasses = resolvePropValue(
    paddingClassMap,
    props.size,
    SIZE_FALLBACK,
    SIZE_CONTEXT,
  )

  let variant = props.disabled ? 'disabled' : props.variant
  let variantClasses = {
    subtle:
      'border border-[--surface-gray-2] bg-surface-gray-2 placeholder-ink-gray-4 hover:border-outline-elevation-2 hover:bg-surface-gray-3 focus:bg-surface-base focus:border-outline-gray-4 focus:shadow-sm focus:ring-0',
    outline:
      'border border-outline-gray-2 bg-surface-base placeholder-ink-gray-4 hover:border-outline-gray-3 hover:shadow-sm focus:bg-surface-base focus:border-outline-gray-4 focus:shadow-sm focus:ring-0',
    disabled: [
      'border bg-surface-gray-1 placeholder-ink-gray-3',
      props.variant === 'outline'
        ? 'border-outline-gray-2'
        : 'border-transparent',
    ],
    ghost: 'border-0 bg-transparent focus:ring-0 focus-visible:outline-none',
  }[variant]

  return [
    sizeClasses,
    paddingClasses,
    variantClasses,
    props.disabled ? 'text-ink-gray-5' : 'text-ink-gray-8',
    'transition-colors w-full block',
  ]
})

let emitChange = (value: string) => {
  emit('update:modelValue', value)
}
if (props.debounce) {
  emitChange = debounce(emitChange, props.debounce)
}

let handleChange = (e: Event) => {
  emitChange((e.target as HTMLInputElement).value)
}

function focus(options?: FocusOptions) {
  textareaRef.value?.focus(options)
}

// A getter rather than `computed(...)`: see TextInput.vue's defineExpose for
// why — a ComputedRef doesn't structurally match the type's plain element.
defineExpose<TextInputExposed<HTMLTextAreaElement>>({
  focus,
  get inputElement() {
    return textareaRef.value
  },
})
</script>
